'use client'

import { toggleNotificationPreference } from '../actions'

type NotificationToggleProps = {
  userId: string
  initialPreference: boolean
}

export function NotificationToggle({ userId, initialPreference }: NotificationToggleProps) {
  async function handleToggle() {
    await toggleNotificationPreference(userId)
  }

  return (
    <div>
      <label>
        <input
          type="checkbox"
          checked={initialPreference}
          onChange={handleToggle}
        />
        <span> Enable Notifications</span>
      </label>
      <p>Current preference: {initialPreference ? 'ON' : 'OFF'}</p>
    </div>
  )
}

